  "timeout": 60
}

{
  "command": "gh project item-list 19 --owner KirkDiggler --limit 1000 --format json | jq '{totalCount, matches: [.items[] | select((.content.number == 216) and (.content.repository == \"KirkDiggler/rpg-project\"))]}'",
  "timeout": 60
}

{
  "command": "gh api graphql -f query='query { repository(owner:\"KirkDiggler\", name:\"rpg-project\") { pullRequest(number:217) { url state isDraft mergeable mergeStateStatus closingIssuesReferences(first:20) { totalCount nodes { number url title state } } reviewRequests(first:20) { totalCount nodes { requestedReviewer { __typename ... on User { login } ... on Team { name slug } } } } } } }'",
  "timeout": 30
}

