  "command": "git ls-remote --heads origin refs/heads/idea/216-attack-die-3d && gh api repos/KirkDiggler/rpg-project/commits/427c3da60db15b1a84ed45d2bb353076666e0ded --jq '{sha: .sha, html_url: .html_url, message: .commit.message, parents: [.parents[].sha]}'",
  "timeout": 30
}

