  "command": "gh issue view 216 --repo KirkDiggler/rpg-project --json body --jq '.body | {lastNonblankLine: (split(\"\\n\") | map(select(length>0)) | last), signatureExactCount: ([scan(\"— asset-pipeline agent, on behalf of KirkDiggler\")] | length)}' && gh pr view 217 --repo KirkDiggler/rpg-project --json body --jq '.body | {lastNonblankLine: (split(\"\\n\") | map(select(length>0)) | last), signatureExactCount: ([scan(\"— asset-pipeline agent, on behalf of KirkDiggler\")] | length), closesExactCount: ([scan(\"Closes #216\")] | length), approvalSentenceExactCount: ([scan(\"The conversational design sections are approved, but Kirk must review and approve this written specification before planning or implementation begins\\\\.\")] | length)}'",
